pub fn report(result: Result<usize, &str>) -> (String, String, u8) {
    match result {
        Ok(n) => (format!("{n}\n"), String::new(), 0),
        Err(e) => (String::new(), format!("error: {e}\n"), 2),
    }
}

fn main() {
    assert_eq!(
        report(Ok(3)),
        (
            "3
"
            .to_owned(),
            "".to_owned(),
            0
        ),
        "case 1"
    );
    assert_eq!(
        report(Ok(0)),
        (
            "0
"
            .to_owned(),
            "".to_owned(),
            0
        ),
        "case 2"
    );
    assert_eq!(
        report(Err("invalid title")),
        (
            "".to_owned(),
            "error: invalid title
"
            .to_owned(),
            2
        ),
        "case 3"
    );
    assert_eq!(
        report(Err("missing input")),
        (
            "".to_owned(),
            "error: missing input
"
            .to_owned(),
            2
        ),
        "case 4"
    );
    println!("worked example passed");
}

